#!/usr/bin/env bun
/**
 * Capture AI Activity heatmap evidence (desktop + mobile, section in frame).
 * Requires local dev on :3000.
 */
import { $ } from "bun";
import { mkdir } from "node:fs/promises";

const OUT =
  "/Users/dhruv2mars/dev/github/portfolio/gauntlet/pieces/ai-activity-heatmap/r1";
await mkdir(OUT, { recursive: true });

async function ab(session: string, ...args: string[]) {
  const r = await $`agent-browser --session ${session} ${args}`.nothrow();
  const out = (r.stdout.toString() + r.stderr.toString()).trim();
  console.log(`[${session}]`, out.slice(0, 500));
  if (r.exitCode !== 0) throw new Error(`agent-browser failed: ${args[0]}`);
  return out;
}

const scrollEval = `(() => {
  document.documentElement.classList.add('dark');
  document.documentElement.classList.remove('light');
  const el = document.querySelector('.ai-activity');
  if (el) el.scrollIntoView({ block: 'center' });
  return JSON.stringify({
    has: !!el,
    h2: el?.querySelector('h2')?.textContent ?? null,
    cells: el?.querySelectorAll('button.activity-cell').length ?? 0,
    accent: getComputedStyle(document.documentElement).getPropertyValue('--color-accent').trim(),
    a4: getComputedStyle(document.documentElement).getPropertyValue('--color-activity-4').trim(),
    w: innerWidth,
    h: innerHeight,
  });
})()`;

// Desktop
await ab("hm-desk", "close").catch(() => {});
await ab("hm-desk", "set", "viewport", "1440", "900");
await ab("hm-desk", "open", "http://localhost:3000/");
await ab("hm-desk", "wait", "3000");
await ab("hm-desk", "eval", scrollEval);
await ab("hm-desk", "wait", "500");
await ab("hm-desk", "screenshot", `${OUT}/heatmap-desktop.png`);
await ab("hm-desk", "close").catch(() => {});

// Mobile — set viewport before open so layout is correct on first paint
await ab("hm-mob", "close").catch(() => {});
await ab("hm-mob", "set", "viewport", "390", "844");
await ab("hm-mob", "open", "http://localhost:3000/");
await ab("hm-mob", "wait", "3000");
await ab("hm-mob", "eval", scrollEval);
await ab("hm-mob", "wait", "500");
await ab("hm-mob", "screenshot", `${OUT}/heatmap-mobile.png`);
await ab("hm-mob", "close").catch(() => {});

console.log("ALL DONE");
